import React, { useEffect, useRef, useState } from 'react';
import * as THREE from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls';

const GlbTest = () => {
  const canvasRef = useRef(null);
  const [mixer, setMixer] = useState(null);

  useEffect(() => {
    // Scene setup
    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(75, 400 / 400, 0.1, 1000);
    const renderer = new THREE.WebGLRenderer({ antialias: true });

    // Renderer settings
    renderer.setSize(400, 400);
    renderer.shadowMap.enabled = true; // Enable shadow maps
    renderer.shadowMap.type = THREE.PCFSoftShadowMap; // Softer shadows
    canvasRef.current.appendChild(renderer.domElement);

    // Add ambient light
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
    scene.add(ambientLight);

    // Add directional light
    const directionalLight = new THREE.DirectionalLight(0xffffff, 0.8);
    directionalLight.position.set(2, 2, 2);
    directionalLight.castShadow = true; // Enable shadows for the directional light
    directionalLight.shadow.mapSize.width = 1024;
    directionalLight.shadow.mapSize.height = 1024;
    directionalLight.shadow.camera.near = 0.5;
    directionalLight.shadow.camera.far = 50;
    scene.add(directionalLight);

    // Optional: Add a fill light to reduce shadow harshness
    const fillLight = new THREE.DirectionalLight(0xffffff, 0.4);
    fillLight.position.set(-1, -1, 2);
    scene.add(fillLight);

    // Load GLB model
    const loader = new GLTFLoader();
    loader.load('/static/models/minheejin.glb', (gltf) => {
      const model = gltf.scene;
      model.traverse((node) => {
        if (node.isMesh) {
          node.castShadow = true; // Allow the model to cast shadows
          node.receiveShadow = true; // Allow the model to receive shadows
        }
      });
      scene.add(model);

      // Set mixer for animation
      const mixer = new THREE.AnimationMixer(model);
      setMixer(mixer);

      // Play default animation if exists
      if (gltf.animations.length > 0) {
        const action = mixer.clipAction(gltf.animations[0]);
        action.play();
      }

      // Camera positioning
      const box = new THREE.Box3().setFromObject(model);
      const center = box.getCenter(new THREE.Vector3());
      const size = box.getSize(new THREE.Vector3());

      // Adjust camera position and look at the model
      camera.position.set(center.x, center.y, size.z * 2);
      camera.lookAt(center);

    }, undefined, (error) => {
      console.error('Error loading GLB file:', error);
    });

    // OrbitControls
    const controls = new OrbitControls(camera, renderer.domElement);
    controls.update();

    // Animation loop
    const animate = () => {
      requestAnimationFrame(animate);

      if (mixer) {
        mixer.update(0.01);
      }

      controls.update();
      renderer.render(scene, camera);
    };

    animate();

    // Cleanup on component unmount
    return () => {
      if (renderer) {
        renderer.dispose();
      }
    };
  }, []);

  const playAnimation = () => {
    if (mixer) {
      mixer.update(0);
      mixer.timeScale = 1; // Play the animation
    }
  };

  return (
    <div>
      <div ref={canvasRef} />
      <button onClick={playAnimation}>Play Animation</button>
    </div>
  );
};

export default GlbTest;
